INSERT INTO `places` VALUES (1,'House of Sampoerna','Museum','Museum bersejarah dengan arsitektur kolonial dan cerita panjang tentang Surabaya.','Taman Sampoerna No. 6, Krembangan','Krembangan','09.00-18.00 WIB','Gratis','(031) 3539000','https://houseofsampoerna.museum','official','https://instagram.com/houseofsampoerna',NULL,NULL,'https://images.unsplash.com/photo-1564399579883-451a5d44ec08?auto=format&fit=crop&w=1200&q=80','active','2026-09-29 20:53:19','2026-09-25 09:16:11'),(2,'C2O Library & Collabtive','Perpustakaan','Ruang baca dan kolaborasi yang mempertemukan buku, gagasan, dan komunitas.','Jl. Dr. Cipto 22, Kel. Dr. Sutomo, Kec. Tegalsari, Surabaya, Indonesia 60264','Tegalsari','Rabu-Minggu, 11.00-21.00 WIB','Gratis','+62 816 1522 1216','https://c2o-library.net','official','https://instagram.com/c2olibrary',-7.2815200,112.7385200,'https://images.unsplash.com/photo-1521587760476-6c12a4b040da?auto=format&fit=crop&w=1200&q=80','active','2026-09-29 20:53:19','2026-09-25 09:16:11'),(3,'Balai Pemuda Surabaya','Ruang Budaya','Ruang publik untuk pertunjukan, pameran, dan pertemuan komunitas kreatif.','Jl. Gubernur Suryo No. 15, Genteng','Genteng','08.00-21.00 WIB','Tergantung kegiatan','(031) 5344601','https://disbudporapar.surabaya.go.id/adinda/portaldata/cagarbudaya/detail/balai-pemuda-surabaya','official_portal','https://instagram.com/balaipemudasurabaya',NULL,NULL,'https://images.unsplash.com/photo-1577083552431-6e5fd01988f5?auto=format&fit=crop&w=1200&q=80','active','2026-09-29 20:53:19','2026-09-25 09:16:11'),(4,'Museum Kematian dan Etnografi Unair','Museum','Museum Kematian dan Etnografi FISIP Universitas Airlangga memperkenalkan kajian etnografi dan kematian dalam konteks museum kampus. Direktori temu.art mengelompokkannya dalam kategori Museum. Wilayah yang tercantum untuk tempat ini adalah Gubeng. Alamat yang tersedia pada data saat ini adalah Jl. Dharmawangsa Dalam, Airlangga, Kec. Gubeng, Surabaya, Jawa Timur 60286. Jam operasional yang tercatat adalah Senin-Jumat 10.00-16.00 WIB; Sabtu-Minggu dan hari libur nasional tutup. Nomor telepon yang tercatat adalah (031) 5034015. Situs yang tercatat dapat diperiksa untuk mencari pembaruan pengelola. Akun Instagram yang tercantum dapat diperiksa untuk pengumuman terbaru. Pastikan kembali alamat, jam layanan, dan ketentuan kunjungan kepada pengelola sebelum berangkat.','Jl. Dharmawangsa Dalam, Airlangga, Kec. Gubeng, Surabaya, Jawa Timur 60286','Gubeng','Senin-Jumat 10.00-16.00 WIB; Sabtu-Minggu dan hari libur nasional tutup',NULL,'(031) 5034015','https://museoetno.fisip.unair.ac.id/','official','https://www.instagram.com/museumetnografi.unair/',-7.2725396,112.7595644,'upload/Museum/01-museum-etnografi-unair.webp','active',NULL,'2026-09-25 09:33:53'),(5,'Museum Surabaya (Gedung Siola)','Museum','Museum Surabaya menempati gedung bersejarah eks-Siola di Jalan Tunjungan. Situs resmi Musea Surabaya menyebut koleksinya mencakup arsip pemerintahan dan barang antik. Koleksi tersebut menggambarkan sejarah dan perkembangan Kota Surabaya. Musea juga menjelaskan bahwa museum ini menjadi ruang edukatif yang merefleksikan identitas kota. Gedung Siola menempatkan cerita museum di salah satu koridor bersejarah Surabaya. Museum Surabaya termasuk dalam jaringan museum yang dihimpun melalui platform Musea Surabaya. Informasi resmi tentang program museum tersedia melalui situs Musea. Periksa kanal resmi sebelum berkunjung untuk memastikan jadwal terbaru.','Jl. Tunjungan No. 1, Genteng, Kec. Genteng, Surabaya, Jawa Timur 60275','Genteng','Senin tutup; Selasa-Minggu 08.00-15.00 WIB','Gratis','0838-3134-6153','https://musea.surabaya.go.id/','official','https://www.instagram.com/wisatakotasurabaya/',-7.2562963,112.7375696,'upload/Museum/04-museum-surabaya-siola.png','active',NULL,'2026-09-25 09:33:53'),(6,'Museum Teknoform Universitas Dinamika','Museum','Museum Teknoform Universitas Dinamika memperkenalkan teknologi dan sejarah perkembangan digital. Direktori temu.art mengelompokkannya dalam kategori Museum. Wilayah yang tercantum untuk tempat ini adalah Rungkut. Alamat yang tersedia pada data saat ini adalah Jl. Raya Kedung Baruk No. 98, Kedung Baruk, Kec. Rungkut, Surabaya, Jawa Timur 60298. Jam operasional yang tercatat adalah Senin-Jumat 09.00-15.00 WIB. Nomor telepon yang tercatat adalah 0851-8126-2101. Situs yang tercatat dapat diperiksa untuk mencari pembaruan pengelola. Akun Instagram yang tercantum dapat diperiksa untuk pengumuman terbaru. Pastikan kembali alamat, jam layanan, dan ketentuan kunjungan kepada pengelola sebelum berangkat.','Jl. Raya Kedung Baruk No. 98, Kedung Baruk, Kec. Rungkut, Surabaya, Jawa Timur 60298','Rungkut','Senin-Jumat 09.00-15.00 WIB',NULL,'0851-8126-2101','https://teknoform.dinamika.ac.id/','official','https://www.instagram.com/museumteknoform/',-7.3118978,112.7822688,'upload/Museum/03-museum-teknoform.png','active',NULL,'2026-09-25 09:33:53'),(8,'Monumen Kapal Selam Surabaya (Monkasel)','Museum','Monumen Kapal Selam Surabaya, atau Monkasel, mengenalkan sejarah KRI Pasopati. Situs resminya menyebut kapal tersebut pernah terlibat dalam operasi pembebasan Irian Barat. Pengunjung dapat menjelajahi bagian dalam kapal selam. Halaman resmi menampilkan ruang mesin sebagai salah satu bagian kapal. Ruang dan palka torpedo juga tercantum pada informasi situs. Kunjungan memberi konteks tentang teknologi kapal selam dan kehidupan di dalamnya. Situs resmi menyebut Monkasel sebagai monumen kapal selam terbesar di Asia. Fasilitas yang dicantumkan meliputi parkir, stan makanan, toko suvenir, toilet, tempat ibadah, dan kafe. Alamat resminya berada di Jalan Pemuda, Surabaya. Saat data diperiksa, situs resmi memuat pemberitahuan tutup sementara; cek kembali sebelum berkunjung.','Jl. Pemuda No. 39, Embong Kaliasin, Kec. Genteng, Surabaya, Jawa Timur 60271','Genteng','Tutup sementara; situs resmi meminta pengunjung memeriksa pengumuman terbaru.',NULL,'(031) 5490410','https://monkasel-surabaya.com/','official','https://www.instagram.com/monkaselsurabaya/',-7.2655910,112.7503272,'upload/Museum/13-monumen-kapal-selam.png','active',NULL,'2026-09-25 09:33:53'),(9,'UYCC Art Gallery','Galeri Seni','UYCC Art Gallery merupakan ruang seni di Surabaya yang dikenal melalui pameran dan percakapan visual. Direktori temu.art mengelompokkannya dalam kategori Galeri Seni. Wilayah yang tercantum untuk tempat ini adalah Genteng. Alamat yang tersedia pada data saat ini adalah Jl. Embong Tanjung No. 46-48, Embong Kaliasin, Kec. Genteng, Surabaya, Jawa Timur 60271. Jam operasional yang tercatat adalah Senin-Minggu 12.00-20.00 WIB. Nomor telepon yang tercatat adalah 0813-3572-0132. Situs yang tercatat dapat diperiksa untuk mencari pembaruan pengelola. Akun Instagram yang tercantum dapat diperiksa untuk pengumuman terbaru. Pastikan kembali alamat, jam layanan, dan ketentuan kunjungan kepada pengelola sebelum berangkat.','Jl. Embong Tanjung No. 46-48, Embong Kaliasin, Kec. Genteng, Surabaya, Jawa Timur 60271','Genteng','Senin-Minggu 12.00-20.00 WIB',NULL,'0813-3572-0132','https://www.instagram.com/uycc.artgallery/','official_source','https://www.instagram.com/uycc.artgallery/',-7.2680621,112.7477999,'upload/Galeri/02-uycc-art-gallery.webp','active',NULL,'2026-09-25 09:33:53'),(10,'Teh Villa Gallery Rungkut Industri','Galeri Seni','Teh Villa Gallery berada di Jalan Raya Rungkut Industri II, Surabaya. Situs resminya memuat daftar pameran yang pernah diselenggarakan. Program galeri menampilkan lukisan dari para pelukis. Pengunjung juga dapat melukis di kanvas yang disediakan oleh galeri. Situs tersebut menyediakan kontak untuk negosiasi karya. Kontak resmi mencakup layanan WhatsApp. Galeri menyatakan sebagian hasil penjualan lukisan disumbangkan kepada pihak yang membutuhkan. Jadwal pameran dapat berubah mengikuti program yang berlangsung. Gunakan kanal resmi untuk menanyakan reservasi, jam kunjungan, dan informasi karya terbaru.','Jl. Raya Rungkut Industri II No. 53, Kali Rungkut, Kec. Rungkut, Surabaya, Jawa Timur 60293','Rungkut','Setiap hari 09.30-15.00 WIB',NULL,'0813-3182-3757','https://tehvillagallery.com/','official','https://www.instagram.com/tehvillagallery/',-7.3285925,112.7639834,'upload/Galeri/04-teh-villa-gallery.png','active',NULL,'2026-09-25 09:33:53'),(11,'Orasis Art Space Bukit Golf','Galeri Seni','Orasis Art Space berada di kawasan Bukit Golf, Sambikerep, Surabaya. Situs resminya menjelaskan bahwa nama Orasis berasal dari bahasa Yunani Kuno yang berarti penglihatan. Dalam konteks ruang seni, Orasis menggambarkan dirinya sebagai gerbang untuk melihat lebih dalam nilai-nilai dalam proses berkesenian. Slogan yang digunakan adalah “Memandang Lebih Dalam, Melihat Lebih Luas”. Situs tersebut menyebut slogan itu mencerminkan tujuan program artistiknya. Program dan pameran dapat berubah dari waktu ke waktu. Google Maps menandai lokasi ini tutup sementara saat data diperiksa. Periksa situs Orasis atau Google Maps sebelum merencanakan kunjungan.','Jl. Bukit Golf No. B2-25, Sambikerep, Kec. Sambikerep, Surabaya, Jawa Timur 60219','Sambikerep','Tutup sementara menurut Google Maps saat diperiksa; cek kanal resmi sebelum berkunjung.',NULL,'0821-2341-1181','https://orasis.art/','official','https://www.instagram.com/orasisartspace/',-7.2833672,112.6434948,'upload/Galeri/05-orasis-art-space.png','active',NULL,'2026-09-25 09:33:53'),(12,'Museum Digital Universitas Airlangga','Museum','Museum Digital Universitas Airlangga menghadirkan cara digital untuk menyusuri sejarah kampus dan Jawa Timur. Direktori temu.art mengelompokkannya dalam kategori Museum. Wilayah yang tercantum untuk tempat ini adalah Sukolilo. Alamat yang tersedia pada data saat ini adalah Surabaya. Jam operasional belum tercantum pada informasi tempat yang tersedia. Nomor telepon serta informasi tiket belum tercantum pada data tempat. Situs yang tercatat dapat diperiksa untuk mencari pembaruan pengelola. Akun Instagram yang tercantum dapat diperiksa untuk pengumuman terbaru. Pastikan kembali alamat, jam layanan, dan ketentuan kunjungan kepada pengelola sebelum berangkat.','Surabaya','Sukolilo',NULL,NULL,NULL,'https://unair.ac.id/museum-digital-unair-cara-baru-menyusuri-sejarah-kampus-timur-jawa-dwipa/','official_source','https://www.instagram.com/unair_official/',NULL,NULL,'upload/Museum/02-museum-digital-unair.webp','active',NULL,'2026-09-25 09:36:06'),(13,'Museum FIB Unair','Museum','Mini museum dengan koleksi dan cerita dari Fakultas Ilmu Budaya Unair.','Surabaya','Sukolilo',NULL,NULL,NULL,'https://fib.unair.ac.id/fib/2025/01/23/intip-koleksi-mini-museum-fib-unair/','official_source',NULL,NULL,NULL,'https://images.unsplash.com/photo-1564399579883-451a5d44ec08?auto=format&fit=crop&w=1200&q=80','active','2026-09-29 20:53:19','2026-09-25 09:36:06'),(14,'Blockbuster Museum Surabaya','Museum','Blockbuster Museum Surabaya adalah museum dengan ruang pamer dan koleksi bertema budaya populer. Direktori temu.art mengelompokkannya dalam kategori Museum. Wilayah yang tercantum untuk tempat ini adalah Tambaksari. Alamat yang tersedia pada data saat ini adalah Jl. Kenjeran No. 463-465, Gading, Kec. Tambaksari, Surabaya, Jawa Timur 60134. Jam operasional yang tercatat adalah Jumat-Minggu 12.00-19.00 WIB. Nomor telepon yang tercatat adalah 0822-2338-1133. Informasi tiket atau akses yang tercatat adalah Mulai Rp80.000. Situs yang tercatat dapat diperiksa untuk mencari pembaruan pengelola. Akun Instagram yang tercantum dapat diperiksa untuk pengumuman terbaru. Pastikan kembali alamat, jam layanan, dan ketentuan kunjungan kepada pengelola sebelum berangkat.','Jl. Kenjeran No. 463-465, Gading, Kec. Tambaksari, Surabaya, Jawa Timur 60134','Tambaksari','Jumat-Minggu 12.00-19.00 WIB','Mulai Rp80.000','0822-2338-1133','https://linktr.ee/museumbms','official_source','https://www.instagram.com/blockbustermuseumsurabaya/',-7.2477541,112.7795727,'upload/Museum/17-blockbuster-museum.webp','active',NULL,'2026-09-25 09:36:06'),(15,'Galeri Prabangkara (Taman Budaya Jatim)','Galeri Seni','Galeri Prabangkara merupakan ruang pamer karya visual di lingkungan Taman Budaya Jawa Timur. Direktori temu.art mengelompokkannya dalam kategori Galeri Seni. Wilayah yang tercantum untuk tempat ini adalah Genteng. Alamat yang tersedia pada data saat ini adalah Jl. Genteng Kali No. 85, Genteng, Kec. Genteng, Surabaya, Jawa Timur 60275. Jam operasional belum tercantum pada informasi tempat yang tersedia. Nomor telepon yang tercatat adalah (0821) 30005785 / (031) 5342128. Situs yang tercatat dapat diperiksa untuk mencari pembaruan pengelola. Akun Instagram yang tercantum dapat diperiksa untuk pengumuman terbaru. Pastikan kembali alamat, jam layanan, dan ketentuan kunjungan kepada pengelola sebelum berangkat.','Jl. Genteng Kali No. 85, Genteng, Kec. Genteng, Surabaya, Jawa Timur 60275','Genteng',NULL,NULL,'(0821) 30005785 / (031) 5342128','https://tiketcakdurasim.com/gedung','official_source','https://www.instagram.com/tamanbudayajatim/',-7.2565236,112.7401734,'upload/Galeri/01-galeri-prabangkara.png','active',NULL,'2026-09-25 09:36:06'),(16,'Vin Autism Gallery Citraland','Galeri Seni','Vin Autism Gallery Citraland mendukung ekspresi seni dan karya seniman autistik. Direktori temu.art mengelompokkannya dalam kategori Galeri Seni. Wilayah yang tercantum untuk tempat ini adalah Sambikerep. Alamat yang tersedia pada data saat ini adalah G-Walk Junction TL 6, Jl. Citraland Surabaya No. 11, Sambikerep, Kec. Sambikerep, Surabaya, Jawa Timur 60217. Jam operasional yang tercatat adalah Senin-Sabtu, 08.00-13.00 WIB (dengan janji temu). Nomor telepon yang tercatat adalah 0821-2269-0238. Situs yang tercatat dapat diperiksa untuk mencari pembaruan pengelola. Akun Instagram yang tercantum dapat diperiksa untuk pengumuman terbaru. Pastikan kembali alamat, jam layanan, dan ketentuan kunjungan kepada pengelola sebelum berangkat.','G-Walk Junction TL 6, Jl. Citraland Surabaya No. 11, Sambikerep, Kec. Sambikerep, Surabaya, Jawa Timur 60217','Sambikerep','Senin-Sabtu, 08.00-13.00 WIB (dengan janji temu)',NULL,'0821-2269-0238','https://vinautismgallery.com/?lang=en','official','https://www.instagram.com/vinautismgallery/',-7.2950762,112.6546951,'upload/Galeri/03-vin-autism-gallery.png','active',NULL,'2026-09-25 09:36:06'),(17,'House of Sampoerna','Museum','Museum bersejarah dengan arsitektur kolonial dan cerita tentang sejarah Surabaya.','Taman Sampoerna No. 6, Krembangan, Surabaya','Krembangan','09.00–18.00 WIB','Gratis','(031) 3539000','https://houseofsampoerna.museum',NULL,'https://www.instagram.com/houseofsampoerna/',NULL,NULL,NULL,'active','2026-09-29 20:53:19','2026-09-27 04:58:34'),(19,'TEST temu art','Museum','museum','ss','Genteng',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'active','2026-09-29 18:56:34','2026-09-27 13:25:52'),(21,'Taman Bacaan Masyarakat Cerdas Ceria Babatan','Taman Baca Masyarakat','Taman Bacaan Masyarakat Cerdas Ceria Babatan tercatat sebagai perpustakaan anak-anak di kawasan Babatan. Direktori temu.art mengelompokkannya dalam kategori Taman Baca Masyarakat. Wilayah yang tercantum untuk tempat ini adalah Wiyung. Alamat yang tersedia pada data saat ini adalah Jl. Babatan III, Babatan, Kec. Wiyung, Surabaya, Jawa Timur 60227. Jam operasional yang tercatat adalah Buka 24 jam menurut Google Maps; konfirmasi ulang sebelum berkunjung.. Nomor telepon yang tercatat adalah 0857-4564-3778. Tautan Google Maps tercantum untuk memeriksa rute dan detail listing yang tersedia. Pastikan kembali alamat, jam layanan, dan ketentuan kunjungan kepada pengelola sebelum berangkat.','Jl. Babatan III, Babatan, Kec. Wiyung, Surabaya, Jawa Timur 60227','Wiyung','Buka 24 jam menurut Google Maps; konfirmasi ulang sebelum berkunjung.',NULL,'0857-4564-3778','https://www.google.com/maps/search/?api=1&query=Taman+Baca+Masyarakat+Cerdas+Ceria+Babatan+III+Surabaya',NULL,NULL,-7.3071521,112.6774459,'upload/Taman%20Baca%20Masyarakat/Gambar%201.%20TBM%20Cerdas%20Ceria%20Babatan.%20Sumber%20Gmaps.jpg','active',NULL,'2026-09-29 12:19:31'),(22,'Taman Baca Masyarakat Griya Ilmu','Taman